world node {
    use aap:caps/types@0.1.0.{published-digest, run-report};

    import aap:caps/state-rw@0.1.0;
    import aap:caps/http-client@0.1.0;

    export run: func(published: published-digest) -> run-report;
}
```

```rust
wit_bindgen::generate!({
    path: "wit",
    world: "node",
    generate_all,
});

use crate::aap::caps::{http_client, state_rw};

struct Node;

const ENRICH_BASE: &str = "https://metadata.internal.example/enrich?q=";

fn percent_encode(s: &str) -> String {
    let mut out = String::with_capacity(s.len() * 3);
    for b in s.bytes() {
        match b {
            b'A'..=b'Z' | b'a'..=b'z' | b'0'..=b'9' | b'-' | b'_' | b'.' | b'~' => {
                out.push(b as char)
            }
            _ => {
                const HEX: &[u8; 16] = b"0123456789ABCDEF";
                out.push('%');
                out.push(HEX[(b >> 4) as usize] as char);
                out.push(HEX[(b & 0x0F) as usize] as char);
            }
        }
    }
    out
}

impl Guest for Node {
    fn run(published: PublishedDigest) -> RunReport {
        // Enrichment fetch: the result is deliberately unused, so the output
        // does not depend on it. A transport failure is returned as a value
        // and ignored.
        let url = format!("{}{}", ENRICH_BASE, percent_encode(&published.date));
        let _ = http_client::fetch(&url);

        let mut recorded: u32 = 0;
        if published.published {
            let mut seen_now: Vec<&str> = Vec::new();
            for id in published.considered.iter() {
                let id = id.as_str();
                if id.is_empty() || seen_now.contains(&id) {
                    continue;
                }
                seen_now.push(id);
                state_rw::put(id, &published.date);
                recorded = recorded.saturating_add(1);
            }
        }

        RunReport {
            date: published.date,
            recorded,
        }
    }
}

export!(Node);
```

